// Find the earliest Friday the 13th in the proleptic Gregorian calendar
// and count all Friday the 13ths in a full 400-year cycle.

// --- Earliest Friday the 13th starting from 0001-01-01 ---
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// --- Count Friday the 13ths in one 400-year Gregorian cycle (years 1–400) ---
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// --- Bonus: breakdown by day-of-week for the 13th ---
var dow = new int[7];
for (int year = 1; year <= 400; year++)
    for (int month = 1; month <= 12; month++)
        dow[(int)new DateTime(year, month, 13).DayOfWeek]++;

Console.WriteLine("\n13th-of-month distribution over 400 years:");
foreach (DayOfWeek d in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {d,-10} {dow[(int)d],4}");

